// wh holds the caption size returned by CMND_2DO_CREATE_TELOP.
// The caption is drawn centred on a point that moves with the animation.
local wh = [0, 0];
CMND_2DO_CREATE_TELOP("skill_name", 0, 12, 0, "whs0035", wh, 6);
local ofs_w = -wh[0] / 2;
local ofs_h = -wh[1] / 2;
local pose = [200 + ofs_w, 204 + ofs_h];
CMND_2DO_POS_SET_TELOP("skill_name", pose[0], pose[1]);
